CREATE TRIGGER IF NOT EXISTS session_attachment_chunks_tapestry_revision_replace_update
BEFORE UPDATE OF ChunkId, AttachmentId, GenerationId, ChunkIndex ON session_attachment_chunks
BEGIN
    INSERT INTO tapestry_scope_revisions(ScopeKind,ScopeId,CorpusRevision,InvalidationRevision)
    SELECT DISTINCT 'SessionAttachment', x.SessionId, 1, 1 FROM session_attachment_chunks x
    WHERE x.rowid <> OLD.rowid AND (x.ChunkId=NEW.ChunkId OR (x.AttachmentId=NEW.AttachmentId AND x.GenerationId=NEW.GenerationId AND x.ChunkIndex=NEW.ChunkIndex)) AND (x.Content IS NOT NULL AND trim(x.Content, char(9,10,11,12,13,32,133,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288)) <> '' AND x.RetrievalScope IS NOT NULL AND lower(trim(substr(x.MimeType,1,instr(x.MimeType || ';',';')-1),' ' || char(9) || char(10) || char(13))) NOT IN ('application/vnd.arcanum.comprehension-text', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/vnd.ms-word.document.macroenabled.12', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.ms-excel.sheet.macroenabled.12', 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 'application/vnd.ms-powerpoint.presentation.macroenabled.12', 'application/vnd.oasis.opendocument.text', 'application/vnd.oasis.opendocument.spreadsheet', 'application/vnd.oasis.opendocument.presentation', 'application/vnd.ms-visio.drawing', 'application/vnd.ms-visio.drawing.macroenabled.12', 'application/pdf'))
    ON CONFLICT(ScopeKind,ScopeId) DO UPDATE SET CorpusRevision=CorpusRevision+1, InvalidationRevision=InvalidationRevision+excluded.InvalidationRevision;
    DELETE FROM tapestry_leaf_hashes WHERE SourceKind='SessionAttachmentChunk' AND SourceId IN (SELECT x.ChunkId FROM session_attachment_chunks x WHERE x.rowid <> OLD.rowid AND (x.ChunkId=NEW.ChunkId OR (x.AttachmentId=NEW.AttachmentId AND x.GenerationId=NEW.GenerationId AND x.ChunkIndex=NEW.ChunkIndex)));
END;
